const inputItem = $input.first()?.json || {};

// 1. Resolve Cost Explorer API data (handles .body, .data, stringified JSON, or direct root)
let ceData = inputItem.body || inputItem.data || inputItem;
if (typeof ceData === 'string') {
  try {
    ceData = JSON.parse(ceData);
  } catch (e) {}
}

const resultsByTime = ceData?.ResultsByTime || inputItem?.ResultsByTime || [];

// 2. Resolve Previous Node Connection Info with robust fallbacks
const prevInfo = 
  $node["Deduplication & Range Check"]?.json || 
  $node["Deduplication & Range Check"]?.json?.documents?.[0] ||
  $node["Code"]?.json ||
  $node["Find Active AWS Connection"]?.json?.documents?.[0] ||
  $node["Find Document"]?.json?.documents?.[0] ||
  inputItem.connection ||
  {};

const now = new Date();
const currentYear = now.getUTCFullYear();
const currentMonth = String(now.getUTCMonth() + 1).padStart(2, '0');
const defaultBillingPeriod = `${currentYear}-${currentMonth}`;

const accountId = prevInfo.awsAccountId || prevInfo.accountId || '864981730114';
const billingPeriod = prevInfo.billingPeriod || defaultBillingPeriod;
const startDate = prevInfo.startDate || `${billingPeriod}-01`;
const nextMonthDate = new Date(Date.UTC(currentYear, now.getUTCMonth() + 1, 1));
const endDate = prevInfo.endDate || nextMonthDate.toISOString().slice(0, 10);
const todayDate = prevInfo.todayDate || now.toISOString().slice(0, 10);

const serviceSummaryMap = {};
const projectSummaryMap = {};
const dailyTotalsMap = {};
const serviceWiseDaily = [];

let totalUnblended = 0;
let totalBlended = 0;
let totalAmortized = 0;
let totalNetUnblended = 0;
let totalNetAmortized = 0;

for (const timeResult of resultsByTime) {
  const date = timeResult.TimePeriod?.Start || '';
  if (!dailyTotalsMap[date]) {
    dailyTotalsMap[date] = {
      date,
      unblendedCost: 0,
      blendedCost: 0,
      amortizedCost: 0,
      netUnblendedCost: 0,
      netAmortizedCost: 0,
      unit: 'USD'
    };
  }

  for (const group of (timeResult.Groups || [])) {
    // Keys[0] is DIMENSION: SERVICE
    const service = group.Keys?.[0] || 'Unknown';

    // Keys[1] is TAG: AWS CE formats tag keys as 'TagName$TagValue' (or 'TagName$' when untagged)
    const rawTag = group.Keys?.[1] || '';
    let projectName = 'Untagged';
    if (rawTag) {
      if (rawTag.includes('$')) {
        const parts = rawTag.split('$');
        projectName = parts.slice(1).join('$').trim() || 'Untagged';
      } else {
        projectName = rawTag.trim() || 'Untagged';
      }
    }

    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');
    const netUnblended = parseFloat(group.Metrics?.NetUnblendedCost?.Amount || '0');
    const netAmortized = parseFloat(group.Metrics?.NetAmortizedCost?.Amount || '0');
    const usageQty = parseFloat(group.Metrics?.UsageQuantity?.Amount || '0');

    // Accumulate Daily Totals
    dailyTotalsMap[date].unblendedCost += unblended;
    dailyTotalsMap[date].blendedCost += blended;
    dailyTotalsMap[date].amortizedCost += amortized;
    dailyTotalsMap[date].netUnblendedCost += netUnblended;
    dailyTotalsMap[date].netAmortizedCost += netAmortized;

    // Accumulate Month Totals
    totalUnblended += unblended;
    totalBlended += blended;
    totalAmortized += amortized;
    totalNetUnblended += netUnblended;
    totalNetAmortized += netAmortized;

    // Accumulate Service Rollup
    if (!serviceSummaryMap[service]) {
      serviceSummaryMap[service] = {
        service,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0,
        netUnblendedCost: 0,
        netAmortizedCost: 0,
        unit: 'USD'
      };
    }
    serviceSummaryMap[service].unblendedCost += unblended;
    serviceSummaryMap[service].blendedCost += blended;
    serviceSummaryMap[service].amortizedCost += amortized;
    serviceSummaryMap[service].netUnblendedCost += netUnblended;
    serviceSummaryMap[service].netAmortizedCost += netAmortized;

    // Accumulate Project Rollup & Per-Project Service Breakdown
    if (!projectSummaryMap[projectName]) {
      projectSummaryMap[projectName] = {
        projectName,
        project_name: projectName,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0,
        netUnblendedCost: 0,
        netAmortizedCost: 0,
        servicesMap: {}
      };
    }
    projectSummaryMap[projectName].unblendedCost += unblended;
    projectSummaryMap[projectName].blendedCost += blended;
    projectSummaryMap[projectName].amortizedCost += amortized;
    projectSummaryMap[projectName].netUnblendedCost += netUnblended;
    projectSummaryMap[projectName].netAmortizedCost += netAmortized;

    if (!projectSummaryMap[projectName].servicesMap[service]) {
      projectSummaryMap[projectName].servicesMap[service] = {
        service,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0
      };
    }
    projectSummaryMap[projectName].servicesMap[service].unblendedCost += unblended;
    projectSummaryMap[projectName].servicesMap[service].blendedCost += blended;
    projectSummaryMap[projectName].servicesMap[service].amortizedCost += amortized;

    if (unblended > 0 || blended > 0 || amortized > 0) {
      serviceWiseDaily.push({
        date,
        service,
        projectName,
        project_name: projectName,
        unblendedCost: Number(unblended.toFixed(4)),
        blendedCost: Number(blended.toFixed(4)),
        amortizedCost: Number(amortized.toFixed(4)),
        usageQuantity: usageQty,
        unit: 'USD'
      });
    }
  }
}

const sortedServices = Object.values(serviceSummaryMap)
  .map(s => ({
    service: s.service,
    unblendedCost: Number(s.unblendedCost.toFixed(2)),
    blendedCost: Number(s.blendedCost.toFixed(2)),
    amortizedCost: Number(s.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const sortedProjects = Object.values(projectSummaryMap)
  .map(p => ({
    projectName: p.projectName,
    project_name: p.project_name,
    unblendedCost: Number(p.unblendedCost.toFixed(2)),
    blendedCost: Number(p.blendedCost.toFixed(2)),
    amortizedCost: Number(p.amortizedCost.toFixed(2)),
    services: Object.values(p.servicesMap)
      .map(s => ({
        service: s.service,
        unblendedCost: Number(s.unblendedCost.toFixed(2)),
        blendedCost: Number(s.blendedCost.toFixed(2)),
        amortizedCost: Number(s.amortizedCost.toFixed(2))
      }))
      .sort((a, b) => b.unblendedCost - a.unblendedCost)
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const dailyTotals = Object.values(dailyTotalsMap)
  .map(d => ({
    date: d.date,
    unblendedCost: Number(d.unblendedCost.toFixed(2)),
    blendedCost: Number(d.blendedCost.toFixed(2)),
    amortizedCost: Number(d.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => a.date.localeCompare(b.date));

const documentToStore = {
  accountId,
  accountName: 'Production AWS Account',
  billingPeriod,
  timePeriod: {
    start: startDate,
    end: endDate
  },
  fetchedAt: new Date(),
  summary: {
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalBlendedCost: Number(totalBlended.toFixed(2)),
    totalNetUnblendedCost: Number(totalNetUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    currency: 'USD'
  },
  serviceSummary: sortedServices,
  projectSummary: sortedProjects,
  dailyTotals,
  serviceWiseDaily,
  totalRecordsCount: serviceWiseDaily.length
};

return {
  json: {
    accountId,
    billingPeriod,
    syncDate: todayDate,
    syncedAt: new Date().toISOString(),
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    serviceCount: sortedServices.length,
    projectCount: sortedProjects.length,
    daysCount: dailyTotals.length,
    document: documentToStore
  }
};

